    "beginner": false,
    "kids": false,
    "note": "茅部郡森町の漁港・港湾の釣り場。岸壁でチカなどの小魚と底の魚を釣り分ける候補。作業岸壁や船の前を避け、現地で利用できる岸を確認して釣り座を選びます。",
    "googleQuery": "北海道 鷲ノ木漁港",
    "verifiedAt": "2026-09-19",
    "access": "北海道茅部郡森町鷲ノ木町29。作業区域を通り抜けず利用できる岸へ向かう。",
