    "bestFor": [
      "小魚の回遊を探す釣り"
    ],
    "timing": "穏やかな天候の日中に下見し、利用範囲と帰りの動線を確認する。",
    "tips": [
      "サビキはまず足元へ落とし、魚が見えなければウキ下や沈める深さを変える。",
      "取り込み用の網を先に用意し、船の係留ロープと交差しない位置から狙う。"
    ],
    "caution": [
      "漁業作業と船の出入りを優先。ゲート・柵の先や立入禁止の堤防へ入らない。",
      "駐車は利用が認められた場所だけにし、漁具置場・作業車の動線を塞がない。",
      "サケ・マスには河口付近の採捕規制がある。対象魚に挙げていない魚を狙う際も、道の最新規則を確認する。"
    ],
    "positionNote": "釣り場資料の地図と国土地理院の地形図を照合した代表点。利用できる岸・釣り座は現地案内を優先。",
